from schemas import make_part


def answer_parts(parts, retrieve, generate):
    questions = list(parts)
    result_parts = []
    supported = 0

    for question in questions:
        sources = retrieve(question)
        sources = list(sources or [])
        if sources:
            supported += 1
            answer = generate(question, sources)
            result_parts.append(
                make_part(question, "answered", answer=answer, sources=sources)
            )
        else:
            result_parts.append(
                make_part(
                    question,
                    "insufficient_evidence",
                    answer=None,
                    sources=[],
                    missing_material=[
                        "No supporting evidence was retrieved for: %s" % (question,)
                    ],
                )
            )

    if supported == len(result_parts) and result_parts:
        status = "answered"
    elif supported == 0:
        status = "insufficient_evidence"
    else:
        status = "partial"

    return {"status": status, "parts": result_parts}

